  "Chat discusses only; it does not operate your device. Sessions stay here.": "mode.chatDescription",
  "对话模式只讨论，不操作设备。会话保存在这台设备上。": "mode.chatDescription",
  "對話模式僅討論，不操作裝置。對話保存在此裝置。": "mode.chatDescription",
  "チャットではデバイスを操作しません。履歴はこのデバイスに保存されます。": "mode.chatDescription",
  "Режим чата не управляет устройством. Сессии хранятся здесь.": "mode.chatDescription",
  "Im Chat wird dein Gerät nicht bedient. Sitzungen bleiben lokal.": "mode.chatDescription",
  "La discussion ne commande pas l’appareil. Les sessions restent ici.": "mode.chatDescription",
  "El chat no controla el dispositivo. Las sesiones se guardan aquí.": "mode.chatDescription",
  "Plan mode observes and prepares steps without modifying your device.": "mode.planDescription",
  "计划模式用于观察与制定步骤，不下发修改操作。": "mode.planDescription",
  "計畫模式用於觀察及制定步驟，不執行修改操作。": "mode.planDescription",
  "計画モードは観察と手順の作成のみを行います。": "mode.planDescription",
  "Режим плана наблюдает и составляет шаги без изменений.": "mode.planDescription",
  "Der Planmodus beobachtet und plant, ohne Änderungen auszuführen.": "mode.planDescription",
  "Le mode Plan observe et prépare les étapes sans modifier l’appareil.": "mode.planDescription",
  "El modo Plan observa y prepara pasos sin modificar el dispositivo.": "mode.planDescription",
  "Task mode executes bounded plans after device binding and authorization.": "mode.taskDescription",
  "任务模式执行有界计划；操作需要完成设备绑定与授权。": "mode.taskDescription",
  "任務模式執行有界計畫；操作需要完成裝置綁定及授權。": "mode.taskDescription",
  "タスクは上限付きで実行します。操作にはデバイスの連携と許可が必要です。": "mode.taskDescription",
  "Задачи выполняют ограниченные планы после привязки и разрешения.": "mode.taskDescription",
  "Der Aufgabenmodus führt begrenzte Pläne nach Gerätefreigabe aus.": "mode.taskDescription",
  "Le mode Tâche exécute des plans limités après association et autorisation.": "mode.taskDescription",
  "El modo Tarea ejecuta planes limitados tras vincular y autorizar el dispositivo.": "mode.taskDescription",
