  "Sessions stay in this browser. Clearing site data or using private browsing may lose them; export important sessions. Credentials stay in memory by default, or can be encrypted locally with a passphrase you enter again after reopening.": "settings.storageHelp",
  "会话保存在此浏览器。清除网站数据或使用隐私浏览可能丢失记录，请主动导出重要会话。API 密钥默认仅存页面内存。可在模型连接中选择口令加密保存，刷新后主动解锁；口令不会保存。": "settings.storageHelp",
  "對話保存在此瀏覽器。清除網站資料或使用私密瀏覽可能遺失記錄，請匯出重要對話。憑證預設只存於記憶體，亦可用口令加密保存在本機；重新開啟後需主動解鎖。": "settings.storageHelp",
  "履歴はこのブラウザに保存されます。サイトデータの削除やプライベートブラウズで失われる場合があるため、重要な履歴は書き出してください。認証情報は既定でメモリのみに保持し、パスフレーズで暗号化して保存することもできます。": "settings.storageHelp",
  "Сессии хранятся в браузере. Очистка данных или приватный режим могут удалить их: экспортируйте важные сессии. Учётные данные по умолчанию остаются в памяти; их можно зашифровать локально с паролем для повторной разблокировки.": "settings.storageHelp",
  "Sitzungen bleiben im Browser. Beim Löschen von Websitedaten oder im privaten Modus können sie verloren gehen. Exportiere wichtige Sitzungen. Zugangsdaten bleiben standardmäßig im Arbeitsspeicher oder werden lokal mit einer Passphrase verschlüsselt.": "settings.storageHelp",
  "Les sessions restent dans le navigateur. L’effacement des données ou la navigation privée peut les supprimer : exportez les sessions importantes. Les identifiants restent en mémoire ou peuvent être chiffrés localement avec une phrase secrète.": "settings.storageHelp",
  "Las sesiones se guardan en este navegador. Al borrar datos o usar navegación privada podrías perderlas; exporta las importantes. Las credenciales quedan en memoria o pueden cifrarse localmente con una contraseña.": "settings.storageHelp",
