  "Extracción local": "context.extractive",
  "Model summaries use the current backend. Local extraction makes no extra model call. Context usage is estimated; full sessions remain local.": "context.help",
  "模型摘要会使用当前账号请求后端；本地提取不额外调用模型。上下文用量为估算值，完整会话仍留在本地。": "context.help",
  "模型摘要會使用目前帳號請求後端；本機擷取不額外呼叫模型。上下文用量為估算值，完整對話仍保留在本機。": "context.help",
  "モデル要約は現在の接続先を使用します。ローカル抽出は追加リクエストを行いません。使用量は推定値で、履歴全体はローカルに残ります。": "context.help",
  "Сводка использует текущую модель. Локальное извлечение не делает дополнительный запрос. Объём контекста оценивается; вся сессия остаётся локально.": "context.help",
  "Modellzusammenfassungen nutzen das aktuelle Konto. Lokale Extraktion benötigt keinen zusätzlichen Modellaufruf. Die Kontextgröße ist geschätzt; der Verlauf bleibt lokal.": "context.help",
  "Le résumé utilise le compte actif. L’extraction locale n’appelle pas de modèle supplémentaire. L’usage est estimé ; la session complète reste locale.": "context.help",
  "El resumen usa la cuenta actual. La extracción local no hace llamadas adicionales. El uso es estimado; la sesión completa queda local.": "context.help",
  "New capture longest side · px": "context.maxSide",
