  "JPEG 质量 · 0.1–1": "context.quality",
  "JPEG 品質 · 0.1–1": "context.quality",
  "Качество JPEG · 0,1–1": "context.quality",
  "JPEG-Qualität · 0,1–1": "context.quality",
  "Qualité JPEG · 0,1–1": "context.quality",
  "Calidad JPEG · 0,1–1": "context.quality",
  "Applies to future captures and attachments. Lower quality can affect text recognition. Saved images are not rewritten.": "context.imageHelp",
  "图片压缩设置用于后续截图与会话附件；低质量可能影响文字识别。不会重写已保存的会话图片。": "context.imageHelp",
  "影像壓縮設定用於後續截圖及對話附件；低品質可能影響文字辨識。不會重寫已儲存的影像。": "context.imageHelp",
  "今後の画像と添付に適用します。低画質は文字認識に影響する場合があります。保存済み画像は変更しません。": "context.imageHelp",
  "Настройки действуют для новых снимков и вложений. Низкое качество может ухудшить распознавание текста. Сохранённые изображения не меняются.": "context.imageHelp",
  "Gilt für neue Aufnahmen und Anhänge. Niedrige Qualität kann die Texterkennung erschweren. Gespeicherte Bilder bleiben unverändert.": "context.imageHelp",
  "S’applique aux prochaines captures et pièces jointes. Une qualité faible peut gêner la lecture. Les images enregistrées ne sont pas modifiées.": "context.imageHelp",
  "Se aplica a futuras capturas y adjuntos. La baja calidad puede dificultar la lectura. Las imágenes guardadas no se modifican.": "context.imageHelp",
