  "Saved. Applies to the next request and capture.": "context.saved",
  "设置已保存，下次请求和截图时生效。": "context.saved",
  "設定已儲存，於下次請求及截圖時生效。": "context.saved",
  "保存しました。次のリクエストと画像取得に適用します。": "context.saved",
  "Сохранено. Применится к следующему запросу и снимку.": "context.saved",
