  "First join the ESP32 setup hotspot and configure Wi-Fi. Identity checks do not grant control permissions.": "device.setupHelp",
  "首次使用先连接 ESP32 配置热点完成配网。当前可检查设备身份；填写地址不会自动授予操作权限。": "device.setupHelp",
  "首次使用請連接 ESP32 設定熱點並完成配網。可檢查裝置身分，但填入網址不會自動授予操作權限。": "device.setupHelp",
  "初回は ESP32 のホットスポットに接続して Wi-Fi を設定してください。ID 確認だけでは操作権限は付与されません。": "device.setupHelp",
  "Сначала настройте Wi-Fi через точку ESP32. Проверка личности устройства не даёт права управления.": "device.setupHelp",
  "Zuerst WLAN über den ESP32-Hotspot einrichten. Eine Identitätsprüfung erteilt keine Steuerberechtigung.": "device.setupHelp",
  "Configurez d’abord le Wi-Fi via le point d’accès ESP32. Le contrôle d’identité n’accorde pas l’autorisation de commande.": "device.setupHelp",
  "Configura primero el Wi-Fi mediante el punto de acceso ESP32. Comprobar la identidad no concede permiso de control.": "device.setupHelp",
